CREATE TABLE growth_account(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,exp BIGINT NOT NULL DEFAULT 0,level INT NOT NULL DEFAULT 1,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_user(user_id));
CREATE TABLE exp_record(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,source VARCHAR(20) NOT NULL,source_id VARCHAR(40) NOT NULL,amount INT NOT NULL,record_date DATE NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_source_user(source,source_id,user_id),INDEX idx_daily(user_id,source,record_date));
CREATE TABLE check_in(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,check_date DATE NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_user_date(user_id,check_date));
